<?php
require_once __DIR__.'/includes/bootstrap.php';require_auth();if(!in_array(role(),['admin','receptionniste','accueil','livreur'],true)){http_response_code(403);exit('Accès réservé à l’équipe de réception et aux livreurs.');}$pdo=db();$isManager=in_array(role(),['admin','receptionniste','accueil'],true);$employeeId=null;
if(!$isManager){$s=$pdo->prepare('SELECT id FROM employes WHERE utilisateur_id=? AND actif=1 ORDER BY id LIMIT 1');$s->execute([$_SESSION['user']['id']]);$employeeId=$s->fetchColumn();if(!$employeeId){$pdo->prepare("INSERT INTO employes(utilisateur_id,nom,poste,actif) VALUES(?,?,'livreur',1)")->execute([$_SESSION['user']['id'],$_SESSION['user']['name']]);$employeeId=(int)db_last_insert_id($pdo,'employes');}}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($isManager&&$action==='create'){$orderId=(int)($_POST['commande_id']??0);$s=$pdo->prepare("SELECT o.id,o.date_promise,c.adresse FROM commandes o JOIN clients c ON c.id=o.client_id WHERE o.id=? AND o.mode_remise='livraison' AND NOT EXISTS(SELECT 1 FROM courses x WHERE x.commande_id=o.id)");$s->execute([$orderId]);$order=$s->fetch();if(!$order)throw new RuntimeException('Commande indisponible pour planifier une livraison.');$pdo->prepare("INSERT INTO courses(commande_id,type,date_prevue,adresse) VALUES(?,'livraison',?,?)")->execute([$orderId,$order['date_promise'],$order['adresse']]);flash('Livraison planifiée.');}elseif($isManager&&$action==='assign'){$courseId=(int)($_POST['course_id']??0);$driverId=(int)($_POST['livreur_id']??0);$s=$pdo->prepare("SELECT id FROM employes WHERE id=? AND poste='livreur' AND actif=1");$s->execute([$driverId]);if(!$s->fetchColumn())throw new RuntimeException('Sélectionnez un livreur actif.');$s=$pdo->prepare("UPDATE courses SET livreur_id=?,date_prevue=?,creneau=?,adresse=? WHERE id=? AND type='livraison'");$s->execute([$driverId,$_POST['date_prevue']??date('Y-m-d'),in_array($_POST['creneau']??'',['matin','apres_midi','soir'],true)?$_POST['creneau']:'matin',trim($_POST['adresse']??''),$courseId]);if(!$s->rowCount()){$check=$pdo->prepare("SELECT id FROM courses WHERE id=? AND type='livraison' AND livreur_id=?");$check->execute([$courseId,$driverId]);if(!$check->fetchColumn())throw new RuntimeException('Course de livraison introuvable.');}flash('Affectation enregistrée.');}elseif(!$isManager&&in_array($action,['start','complete'],true)){$courseId=(int)($_POST['course_id']??0);$pdo->beginTransaction();$s=$pdo->prepare("SELECT co.id,co.statut AS course_status,co.commande_id,o.statut AS order_status,o.total,COALESCE((SELECT SUM(p.montant) FROM paiements p WHERE p.commande_id=o.id),0) AS paid FROM courses co JOIN commandes o ON o.id=co.commande_id WHERE co.id=? AND co.livreur_id=? AND co.type='livraison' FOR UPDATE");$s->execute([$courseId,$employeeId]);$course=$s->fetch();if(!$course)throw new RuntimeException('Cette livraison ne vous est pas attribuée.');if($course['order_status']!=='pret'||(float)$course['paid']<(float)$course['total'])throw new RuntimeException('La commande doit être prête et entièrement payée avant le départ ou la confirmation.');if($action==='start'){if($course['course_status']!=='planifiee')throw new RuntimeException('Cette livraison n’est plus au statut planifiée.');$pdo->prepare("UPDATE courses SET statut='en_cours' WHERE id=? AND livreur_id=?")->execute([$courseId,$employeeId]);flash('Départ de livraison enregistré.');}else{if($course['course_status']!=='en_cours')throw new RuntimeException('Démarrez la livraison avant de la confirmer.');$pdo->prepare("UPDATE commandes SET statut='retire' WHERE id=?")->execute([(int)$course['commande_id']]);$pdo->prepare("UPDATE courses SET statut='effectuee',date_realisation=NOW() WHERE id=? AND livreur_id=?")->execute([$courseId,$employeeId]);flash('Livraison confirmée.');}$pdo->commit();}else{throw new RuntimeException('Action non autorisée.');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Impossible d’enregistrer cette opération.','error');}redirect('livreur.php');}
$page_title=$isManager?'Gestion des livraisons':'Mes livraisons';require 'includes/header.php';
if($isManager){$drivers=$pdo->query("SELECT e.id,CONCAT_WS(' ',NULLIF(e.prenom,''),e.nom) AS name,u.email FROM employes e LEFT JOIN utilisateurs u ON u.id=e.utilisateur_id WHERE e.poste='livreur' AND e.actif=1 ORDER BY e.nom,e.prenom")->fetchAll();$pending=$pdo->query("SELECT o.id,o.reference,o.date_promise,c.nom,c.prenom,c.adresse FROM commandes o JOIN clients c ON c.id=o.client_id WHERE o.mode_remise='livraison' AND NOT EXISTS(SELECT 1 FROM courses x WHERE x.commande_id=o.id) ORDER BY o.date_promise,o.id LIMIT 100")->fetchAll();$courses=$pdo->query("SELECT co.id AS course_id,co.date_prevue,co.creneau,co.adresse,co.statut AS course_status,co.frais,o.id AS order_id,o.reference,o.statut AS order_status,o.total,c.nom,c.prenom,c.telephone,CONCAT_WS(' ',NULLIF(e.prenom,''),e.nom) AS driver_name,e.id AS driver_id FROM courses co JOIN commandes o ON o.id=co.commande_id JOIN clients c ON c.id=o.client_id LEFT JOIN employes e ON e.id=co.livreur_id WHERE co.type='livraison' ORDER BY co.date_prevue DESC,co.id DESC LIMIT 150")->fetchAll();?>
<div class="panel"><div class="panel-head"><h2>Planifier une livraison</h2></div><?php if(!$pending):?><p class="empty">Aucune commande de livraison sans course à planifier.</p><?php else:?><form method="post" class="actions delivery-create"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create"><div class="field"><label>Commande</label><select name="commande_id" required><?php foreach($pending as $o):?><option value="<?=$o['id']?>"><?=e($o['reference'].' · '.$o['prenom'].' '.$o['nom'].' · '.$o['date_promise'])?></option><?php endforeach;?></select></div><button class="btn">Créer la course</button></form><?php endif;?></div>
<div class="panel"><h2>Courses de livraison</h2><?php if(!$drivers):?><p class="notice">Créez d’abord un compte avec le rôle « Livreur » dans Utilisateurs pour pouvoir attribuer une course.</p><?php endif;?><div class="delivery-list"><?php foreach($courses as $course):?><article class="delivery-card"><div class="delivery-card-head"><div><span class="badge <?=e($course['course_status'])?>"><?=e(course_status_label($course['course_status']))?></span><h3><?=e($course['reference'])?> · <?=e($course['prenom'].' '.$course['nom'])?></h3></div><strong><?=e(date('d/m/Y',strtotime($course['date_prevue'])))?> · <?=e(delivery_slot_label($course['creneau']))?></strong></div><p><b>Adresse :</b> <?=e($course['adresse']?:'Adresse non renseignée')?> · <b>Téléphone :</b> <a href="tel:<?=e($course['telephone'])?>"><?=e($course['telephone'])?></a></p><p><b>Statut commande :</b> <?=e(status_label($course['order_status']))?> · <b>Livreur :</b> <?=e($course['driver_name']?:'Non attribué')?></p><form method="post" class="delivery-assign"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="course_id" value="<?=$course['course_id']?>"><div class="field"><label>Livreur</label><select name="livreur_id" required><option value="">Choisir un livreur</option><?php foreach($drivers as $driver):?><option value="<?=$driver['id']?>" <?=$course['driver_id']==$driver['id']?'selected':''?>><?=e($driver['name']?:$driver['email'])?></option><?php endforeach;?></select></div><div class="field"><label>Date</label><input type="date" name="date_prevue" value="<?=e($course['date_prevue'])?>" required></div><div class="field"><label>Créneau</label><select name="creneau"><option value="matin" <?=$course['creneau']==='matin'?'selected':''?>>Matin</option><option value="apres_midi" <?=$course['creneau']==='apres_midi'?'selected':''?>>Après-midi</option><option value="soir" <?=$course['creneau']==='soir'?'selected':''?>>Soir</option></select></div><div class="field"><label>Adresse</label><input name="adresse" value="<?=e($course['adresse']??'')?>"></div><button class="btn small">Enregistrer</button></form></article><?php endforeach;?><?php if(!$courses):?><p class="empty">Aucune livraison planifiée.</p><?php endif;?></div></div>
<?php }else{$s=$pdo->prepare("SELECT co.id AS course_id,co.date_prevue,co.creneau,co.adresse,co.statut AS course_status,o.reference,o.statut AS order_status,o.total,c.nom,c.prenom,c.telephone,COALESCE(NULLIF(co.adresse,''),c.adresse) AS delivery_address,COALESCE((SELECT SUM(p.montant) FROM paiements p WHERE p.commande_id=o.id),0) AS paid FROM courses co JOIN commandes o ON o.id=co.commande_id JOIN clients c ON c.id=o.client_id WHERE co.type='livraison' AND co.livreur_id=? ORDER BY CASE co.statut WHEN 'en_cours' THEN 0 WHEN 'planifiee' THEN 1 ELSE 2 END,co.date_prevue,co.id");$s->execute([$employeeId]);$courses=$s->fetchAll();?><div class="courier-intro"><h2>Bonjour <?=e($_SESSION['user']['name'])?></h2><p class="muted">Voici les livraisons qui vous sont attribuées.</p></div><section class="panel courier-map-panel"><div class="panel-head"><div><h2>Carte du livreur</h2><p class="muted">Activez la localisation pour voir votre position et ouvrir l’adresse du client dans OpenStreetMap.</p></div><button class="btn" type="button" data-locate-driver>Me localiser</button></div><div id="courierMap" class="courier-map" role="region" aria-label="Carte de localisation du livreur"></div><p class="muted" data-location-status aria-live="polite">La carte affiche votre position lorsque vous l’autorisez.</p></section><div class="delivery-list"><?php foreach($courses as $course):$ready=$course['order_status']==='pret'&&(float)$course['paid']>=(float)$course['total'];?><article class="delivery-card courier-card"><div class="delivery-card-head"><div><span class="badge <?=e($course['course_status'])?>"><?=e(course_status_label($course['course_status']))?></span><h2><?=e($course['reference'])?></h2></div><strong><?=e(date('d/m/Y',strtotime($course['date_prevue'])))?> · <?=e(delivery_slot_label($course['creneau']))?></strong></div><p class="delivery-customer"><?=e($course['prenom'].' '.$course['nom'])?></p><p><b>Adresse :</b> <?=e($course['delivery_address']?:'Adresse non renseignée')?></p><p><b>Téléphone :</b> <a href="tel:<?=e($course['telephone'])?>"><?=e($course['telephone'])?></a></p><p><b>Commande :</b> <?=e(status_label($course['order_status']))?> · <b>Total :</b> <?=money($course['total'])?> · <b>Payé :</b> <?=money($course['paid'])?></p><?php if($course['delivery_address']):?><a class="btn light" target="_blank" rel="noopener noreferrer" href="https://www.openstreetmap.org/search?query=<?=rawurlencode($course['delivery_address'])?>">Voir l’adresse sur la carte</a><?php endif;?><?php if($course['course_status']==='planifiee'&&$ready):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="course_id" value="<?=$course['course_id']?>"><button class="btn green" name="action" value="start">Commencer la livraison</button></form><?php elseif($course['course_status']==='en_cours'&&$ready):?><form method="post" data-confirm="Confirmer que cette commande a bien été remise au client ?"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="course_id" value="<?=$course['course_id']?>"><button class="btn green" name="action" value="complete">Confirmer la livraison</button></form><?php elseif(in_array($course['course_status'],['planifiee','en_cours'],true)):?><p class="notice">Le départ est autorisé lorsque la commande est prête et entièrement payée.</p><?php endif;?></article><?php endforeach;?><?php if(!$courses):?><div class="panel empty">Aucune livraison ne vous est attribuée pour le moment.</div><?php endif;?></div><link rel="stylesheet" href="assets/vendor/leaflet.css"><script src="assets/vendor/leaflet.js" defer></script><script src="assets/js/courier-map.js" defer></script><?php }require 'includes/footer.php';
